mapper.sql:
WHERE NVL(sh.is_deleted, 0) = 0

    AND (
        LOWER(sh.title) LIKE LOWER(#{keywordLikePattern}) ESCAPE '!'
        OR LOWER(sh.content) LIKE LOWER(#{keywordLikePattern}) ESCAPE '!'
        OR EXISTS (
            SELECT 1
            FROM send_target_tag stt
            JOIN tag t ON t.id = stt.tag_id AND NVL(t.is_deleted, 0) = 0
            WHERE stt.send_history_id = sh.id
              AND NVL(stt.is_deleted, 0) = 0
              AND LOWER(t.name) LIKE LOWER(#{keywordLikePattern}) ESCAPE '!'
        )
    )


    AND EXISTS (
        SELECT 1
        FROM send_history_routing shr
        WHERE shr.send_history_id = sh.id
          AND shr.channel_id = #{channelId}
          AND NVL(shr.is_deleted, 0) = 0
    )


    AND sh.status = #{status}


    AND sh.purpose = #{purpose}


    AND (
        SELECT COUNT(DISTINCT stt.tag_id)
        FROM send_target_tag stt
        WHERE stt.send_history_id = sh.id
          AND NVL(stt.is_deleted, 0) = 0
          AND stt.tag_id IN

            #{tagId}

    ) = #{tagCount}


    AND sh.scheduled_at >= #{startAt}


    AND sh.scheduled_at < #{endAtExclusive}

mapper.select:
SELECT DISTINCT shr.send_history_id, c.channel_type AS channel_name FROM send_history_routing shr JOIN channel c ON c.id = shr.channel_id AND NVL(c.is_deleted, 0) = 0 WHERE NVL(shr.is_deleted, 0) = 0 AND shr.send_history_id IN
#{historyId}
ORDER BY shr.send_history_id, channel_name

SELECT tag_rows.send_history_id, tag_rows.tag_name FROM ( SELECT DISTINCT stt.send_history_id, t.id AS tag_id, t.name AS tag_name FROM send_target_tag stt JOIN tag t ON t.id = stt.tag_id AND NVL(t.is_deleted, 0) = 0 WHERE NVL(stt.is_deleted, 0) = 0 AND stt.send_history_id IN
#{historyId}
) tag_rows ORDER BY tag_rows.send_history_id, tag_rows.tag_id ASC
